mapper.select:
SELECT l.id, l.log_no, l.platform, l.shop_id, s.shop_name, l.sync_type, l.total_count, l.success_count, l.fail_count, l.unmapped_count, l.sync_status, l.error_message, l.sync_time, l.duration, l.create_time FROM wms_fbo_sync_log l LEFT JOIN shop s ON l.shop_id = s.id
AND l.platform = #{qo.platform}
AND l.shop_id = #{qo.shopId}
AND l.sync_type = #{qo.syncType}
AND l.sync_status = #{qo.syncStatus}
AND l.sync_time >= #{qo.syncTimeStart}
AND l.sync_time <= #{qo.syncTimeEnd}
ORDER BY l.create_time DESC
